facilityFormItem.valueChangedEventHandler:
          var initiatorId = formItem.value || functions.getValues().Initiator;
          functions.setValue('InitiatorId', initiatorId);
          if (initiatorId != null) {
            var urlGetInfo = `/api/functions/PartTimeHasPerformingVacations?employeeId=${initiatorId}&isSelfRecall=true`;
            ESS.network.sendRequest(urlGetInfo)
            .then(function (info) {
              if (info){
                ESS.toasts.hideToast(window.partTimeHasPerformingVacations);
                window.partTimeHasPerformingVacations = ESS.toasts.showToast(info, ESS.enums.ToastType.ERROR, false);
              }
            })    

            context.checkEmployeeConsentSigned({ functions, context, employeeId: initiatorId });

            var recallDate = functions.getValues().RecallDate;
            var vacationId = functions.getValues().VacationId;
            if (recallDate) {
              var options = { dateStyle: "long" };
              var recallDateFromControl = new Date(recallDate).toLocaleString("ru-RU", options);
              functions.setValue('Field_Дата выхода на работу', recallDateFromControl);
              var urlGetRecallVacation = `/api/functions/GetRecallVacations?employeeId=${initiatorId}&recallDate=${recallDate}`;
              ESS.network.sendRequest(urlGetRecallVacation)
              .then(function (vacation){
                var dateStart = new Date(vacation.dateStart);
                var dateEnd = new Date(vacation.dateEnd);
                var dateRecall = new Date(recallDate);
                dateStart.setHours(0, 0, 0, 0);
                dateEnd.setHours(0, 0, 0, 0);
                dateRecall.setHours(0, 0, 0, 0);

                if (dateRecall >= dateStart && dateRecall <= dateEnd){
                  var rows = functions.getValues().NewVacationDateGrid;
                  var vacationKindIdsArray = [];
                  var vacationDurationArray = [];
                  var Compensation = functions.getValues().Compensation;
                  rows.forEach(row => {
                    if (row.rowValues.VacationDuration != null) {
                      vacationKindIdsArray.push(row.rowValues.VacationKindId);
                      vacationDurationArray.push(row.rowValues.VacationDuration);
                    };
                  });
                  ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId: vacation.id, vacationKindIdsArray, vacationDurationArray, Compensation });
                  ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId: vacation.id, vacationKindIdsArray, vacationDurationArray, Compensation });
                }

                var isVacation = vacation.id > 0;
                functions.setIsItemDisabled('NewVacationDateGrid', !isVacation, 'BeginDate');
                functions.setIsItemDisabled('NewVacationDateGrid', !isVacation, 'VacationDuration');
                if (isVacation) {
                  if (vacation.id != vacationId) {
                    var rows = functions.getValues().NewVacationDateGrid;
                    rows.forEach(row => {
                      functions.removeItem('NewVacationDateGrid', row.rowIndex);
                    });
                    functions.setValue('VacationId', vacation.id);
                    ESS.network.sendRequest(`/api/functions/IsCompensationVisible?vacationId=${vacation.id}`)
                    .then(function (isCompVisible){
                      functions.setIsItemHidden('Compensation', !isCompVisible);
                    });
                  }
                }
                else if (vacationId) {
                  functions.setValue('VacationId', null);
                  functions.setIsItemHidden('Compensation', true);
                  functions.setValue('Compensation', false);
                  var rows = functions.getValues().NewVacationDateGrid;
                  rows.forEach(row => {
                    functions.removeItem('NewVacationDateGrid', row.rowIndex);
                  });
                }
              })
              .catch(function (error) {
                ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
              });
            }
          }

          var initiatorId = functions.getValues().Initiator;
          var recallDate = formItem.value;
          var vacationId = functions.getValues().VacationId;
          if (recallDate) {
            var options = { dateStyle: "long" };
            var recallDateFromControl = new Date(recallDate).toLocaleString("ru-RU", options);
            functions.setValue('Field_Дата выхода на работу', recallDateFromControl);
            var urlGetRecallVacation = `/api/functions/GetRecallVacations?employeeId=${initiatorId}&recallDate=${recallDate}`;
            ESS.network.sendRequest(urlGetRecallVacation)
            .then(function (vacation){
              var dateStart = new Date(vacation.dateStart);
              var dateEnd = new Date(vacation.dateEnd);
              var dateRecall = new Date(recallDate);
              dateStart.setHours(0, 0, 0, 0);
              dateEnd.setHours(0, 0, 0, 0);
              dateRecall.setHours(0, 0, 0, 0);

              if (dateRecall >= dateStart && dateRecall <= dateEnd){
                var rows = functions.getValues().NewVacationDateGrid;
                var vacationKindIdsArray = [];
                var vacationDurationArray = [];
                var Compensation = functions.getValues().Compensation;
                rows.forEach(row => {
                  if (row.rowValues.VacationDuration != null) {
                    vacationKindIdsArray.push(row.rowValues.VacationKindId);
                    vacationDurationArray.push(row.rowValues.VacationDuration);
                  };
                });
                ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId: vacation.id, vacationKindIdsArray, vacationDurationArray, Compensation });
                ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId: vacation.id, vacationKindIdsArray, vacationDurationArray, Compensation });
              }

              var isVacation = vacation.id > 0;
              functions.setIsItemDisabled('NewVacationDateGrid', !isVacation, 'BeginDate');
              functions.setIsItemDisabled('NewVacationDateGrid', !isVacation, 'VacationDuration');
              if (isVacation) {
                if (vacation.id != vacationId) {
                  var rows = functions.getValues().NewVacationDateGrid;
                  rows.forEach(row => {
                    functions.removeItem('NewVacationDateGrid', row.rowIndex);
                  });
                  functions.setValue('VacationId', vacation.id);
                  ESS.network.sendRequest(`/api/functions/IsCompensationVisible?vacationId=${vacation.id}`)
                  .then(function (isCompVisible){
                    functions.setIsItemHidden('Compensation', !isCompVisible);
                  });
                }
              }
              else if (vacationId) {
                functions.setValue('VacationId', null);
                functions.setIsItemHidden('Compensation', true);
                functions.setValue('Compensation', false);
                var rows = functions.getValues().NewVacationDateGrid;
                rows.forEach(row => {
                  functions.removeItem('NewVacationDateGrid', row.rowIndex);
                });
              }
            })
            .catch(function (error) {
              ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
            });
          }

          var vacationId = formItem.value;
          var initiatorId = functions.getValues().Initiator;
          ESS.network.sendRequest(`/api/functions/GetVacationPeriodInfo?vacationId=${vacationId}`)
          .then(function (vacationInfo) {
            functions.setValue('VacationPeriod', vacationInfo);
          });

          if (vacationId) {
            var recallDate = functions.getValues().RecallDate;
            var Compensation = functions.getValues().Compensation;
            var rows = functions.getValues().NewVacationDateGrid;
            var vacationKindIdsArray = [];
            var beginDateArray = [];
            var vacationDurationArray = [];
            var endDateArray = [];
            rows.forEach(row => {
              if (row.rowValues.BeginDate != null && row.rowValues.VacationDuration != null) {
                vacationKindIdsArray.push(row.rowValues.VacationKindId);
                var beginDate = `"${row.rowValues.BeginDate}"`;
                beginDateArray.push(beginDate);
                vacationDurationArray.push(row.rowValues.VacationDuration);
                var endDate = `"${row.rowValues.EndDate}"`;
                endDateArray.push(endDate);
              };
            });
            if (vacationId !== null){
              ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
              ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId: vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
            }

            var urlIsRequiredDurationBroken = `/api/functions/CheckEmployeeVacationsDurations?vacationId=${vacationId}&employeeId=${initiatorId}&recallDate=${recallDate}`;
            var urlIsVacationMainKind = `/api/functions/CheckIsMainVacationKind?vacationId=${vacationId}&employeeId=${initiatorId}`;
            ESS.network.sendRequest(urlIsVacationMainKind).then(function(isVacationMainKind){
              if(isVacationMainKind)
              {
                ESS.network.sendRequest(urlIsRequiredDurationBroken).then(function (isDurationBroken){
                if(!isDurationBroken){
                  urlIsRequiredDurationBroken = `/api/functions/CheckVacationRequiredDuration?vacationIds=[${vacationId}]&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
                  ESS.network.sendRequest(urlIsRequiredDurationBroken).then(function (vacationDurationError){
                    if (vacationDurationError){
                      var toastId = ESS.toasts.showToast(vacationDurationError, ESS.enums.ToastType.ERROR, true);
                      functions.setValue('IsRequiredDurationBroken', true);
                    }
                    else {
                      ESS.toasts.hideToast(toastId);
                      functions.setValue('IsRequiredDurationBroken', false);
                    }
                  }); 
                }
                });
              }
            });
          }

facilityFormItem.itemAddedEventHandler:
var vacationId = functions.getValues()['VacationId'];
if (vacationId) {
  ESS.network.sendRequest(`/api/functions/GetVacationKindIdFromVacationId?vacationId=${vacationId}`)
  .then(function (vacationKindId) {
    var table = functions.getValues().NewVacationDateGrid;
    var rowindex = table.length - 1;
    var itemIndex = table[rowindex].rowIndex;
    functions.setValue('NewVacationDateGrid', vacationKindId, itemIndex, 'VacationKindId');
  })
  .catch(function (error) {
    ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
  });
}

facilityFormItem.itemRemovedEventHandler:
          var recallDate = functions.getValues().RecallDate;
          var vacationId = functions.getValues()['VacationId'];
          var Compensation = functions.getValues().Compensation;
          var rows = functions.getValues().NewVacationDateGrid;
          var vacationKindIdsArray = [];
          var beginDateArray = [];
          var vacationDurationArray = [];
          var endDateArray = [];
          var VacationsData = '';
          rows.forEach(row => {
            if (row.rowValues.BeginDate != null && row.rowValues.VacationDuration != null) {
              vacationKindIdsArray.push(row.rowValues.VacationKindId);
              var beginDate = `"${row.rowValues.BeginDate}"`;
              beginDateArray.push(beginDate);
              vacationDurationArray.push(row.rowValues.VacationDuration);
              var endDate = `"${row.rowValues.EndDate}"`;
              endDateArray.push(endDate);
              VacationsData += row.rowValues.VacationKindId + '~' + row.rowValues.BeginDate + '~' + row.rowValues.EndDate +'!';
            };
          });
          functions.setValue('VacationsData', VacationsData);

          if (vacationId) {
            var urlIsCompensationEnable = `/api/functions/IsCompensationEnable?recallDate=${recallDate}&vacationId=${vacationId}&durations=[${vacationDurationArray}]`;
            ESS.network.sendRequest(urlIsCompensationEnable).then(function (isCompEnable){
              functions.setIsItemDisabled('Compensation', !isCompEnable);
            });

            ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
            ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });

            var urlTemplate = `/api/functions/CheckExecutionShiftVacations?vacationIds=[${vacationId}]`;
            ESS.network.sendRequest(urlTemplate).then(function (errors){
              if(errors.length > 0) {
                functions.removeError(window.errorExecutionShift);
                window.errorExecutionShift = functions.showError(errors);
              } else {
                functions.removeError(window.errorExecutionShift);
              }
            });
          }

column.valueChangedEventHandler:
var today = new Date();
var yesterday = new Date(today);
yesterday.setDate(today.getDate() -1);
var beginDateValue = formItem.value;
var dateFromControl = new Date(beginDateValue).getTime();
functions.removeError(window.errorDate);
if (dateFromControl < yesterday.getTime()) {
  window.errorDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_BEGIN'));
}
var initiatorId = functions.getValues().Initiator;
var durationValue = functions.getValues().NewVacationDateGrid.find(function (x) {
  return x.rowIndex === formItem.index;
}).rowValues['VacationDuration'];
var vacationKindId = functions.getValues().NewVacationDateGrid.find(function (x) {
  return x.rowIndex === formItem.index;
}).rowValues['VacationKindId'];

if (durationValue != null && beginDateValue != null) {
  var url = `/api/functions/GetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${initiatorId}&vacationKindId=${vacationKindId}`;
  context.sendRequest(url)
  .then(function (newEndDateValue) {
    functions.setValue('NewVacationDateGrid', newEndDateValue, formItem.index, 'EndDate');
  });
};

var initiatorId = functions.getValues().Initiator;
var beginDateValue = functions.getValues().NewVacationDateGrid.find(function (x) {
  return x.rowIndex === formItem.index;
}).rowValues['BeginDate'];
var durationValue = functions.getValues().NewVacationDateGrid.find(function (x) {
  return x.rowIndex === formItem.index;
}).rowValues['VacationDuration'];
var vacationKindId = functions.getValues().NewVacationDateGrid.find(function (x) {
  return x.rowIndex === formItem.index;
}).rowValues['VacationKindId'];

if (durationValue <= 0) {
  functions.removeError(window.errorId);
  window.errorId = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DURATION'));
} else {
  functions.removeError(window.errorId);
}

if (durationValue != null && beginDateValue != null) {
  var endDate = functions.getValues().NewVacationDateGrid.find(function (x) {
    return x.rowIndex === formItem.index;
  }).rowValues['EndDate'];
  var url = `/api/functions/GetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${initiatorId}&vacationKindId=${vacationKindId}`;
  context.sendRequest(url)
  .then(function (newEndDateValue) {
    if (new Date(newEndDateValue).getTime() != new Date(endDate).getTime()) {
      functions.setValue('NewVacationDateGrid', newEndDateValue, formItem.index, 'EndDate');
    }
  });
};

              var initiatorId = functions.getValues().Initiator;
              var beginDate = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['BeginDate'];
              var endDate = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['EndDate'];
              var vacationKindId = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['VacationKindId'];
              functions.removeError(window.errorEndDate);
              if (beginDate != null && endDate != null && vacationKindId != null) {
                var checkUrl = `/api/functions/CheckVacationHasHoliday?periodBegin=${beginDate}&periodEnd=${endDate}&employeeId=${initiatorId}&vacationKindId=${vacationKindId}`;
                context.sendRequest(checkUrl)
                .then(function (warning) {
                  if(warning.length > 0)
                    ESS.toasts.showToast(warning, ESS.enums.ToastType.ERROR, true);
                });

                var url = `/api/functions/DurationInCalendarDaysWithoutHoliday?startDate=${beginDate}&endDate=${endDate}&userId=${initiatorId}&vacationKindId=${vacationKindId}`
                context.sendRequest(url)
                .then(function (newDuration) {
                  if (newDuration <= 0) {
                    window.errorEndDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_END'));
                  }
                  else {
                    var recallDate = functions.getValues().RecallDate;
                    var vacationId = JSON.parse(functions.getValues()['VacationId']);
                    var Compensation = functions.getValues().Compensation;
                    var rows = functions.getValues().NewVacationDateGrid;
                    var vacationKindIdsArray = [];
                    var beginDateArray = [];
                    var vacationDurationArray = [];
                    var endDateArray = [];
                    var VacationsData = '';
                    rows.forEach(row => {
                      if (row.rowValues.BeginDate != null && row.rowValues.VacationDuration != null) {
                        vacationKindIdsArray.push(row.rowValues.VacationKindId);
                        var beginDate = `"${row.rowValues.BeginDate}"`;
                        beginDateArray.push(beginDate);
                        vacationDurationArray.push(row.rowValues.VacationDuration);
                        var endDate = `"${row.rowValues.EndDate}"`;
                        endDateArray.push(endDate);
                        VacationsData += row.rowValues.VacationKindId + '~' + row.rowValues.BeginDate + '~' + row.rowValues.EndDate +'!';
                      };
                    });
                    functions.setValue('VacationsData', VacationsData);

                    var urlIsCompensationEnable = `/api/functions/IsCompensationEnable?recallDate=${recallDate}&vacationId=${vacationId}&durations=[${vacationDurationArray}]`;
                    context.sendRequest(urlIsCompensationEnable).then(function (isCompEnable){
                      functions.setIsItemDisabled('Compensation', !isCompEnable);
                      if (!isCompEnable)
                        functions.setValue('Compensation', false);
                    });

                    ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });

                    var urlTemplate = `/api/functions/CheckAllVacationShiftDates?vacationIds=[${vacationId}]&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
                    context.sendRequest(urlTemplate).then(function (errors){
                      if(errors.length > 0) {
                        functions.removeError(window.errorVacations);
                        window.errorVacations = functions.showError(errors);
                      } else {
                        functions.removeError(window.errorVacations);
                      }
                    });
                    if (vacationKindIdsArray.length > 0) {
                      ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
                    };
                    var urlTemplate = `/api/functions/CheckExecutionShiftVacations?vacationIds=[${vacationId}]`;
                    context.sendRequest(urlTemplate).then(function (errors){
                      if(errors.length > 0) {
                        functions.removeError(window.errorExecutionShift);
                        window.errorExecutionShift = functions.showError(errors);
                      } else {
                        functions.removeError(window.errorExecutionShift);
                      }
                    });

                    var urlIsRequiredDurationBroken = `/api/functions/CheckEmployeeVacationsDurations?vacationId=${vacationId}&employeeId=${initiatorId}&recallDate=${recallDate}`;
                    var urlIsVacationMainKind = `/api/functions/CheckIsMainVacationKind?vacationId=${vacationId}&employeeId=${initiatorId}`;
                    context.sendRequest(urlIsVacationMainKind).then(function(isVacationMainKind){
                      if(isVacationMainKind)
                      {
                        ESS.network.sendRequest(urlIsRequiredDurationBroken).then(function (isDurationBroken){
                        if(!isDurationBroken){
                          urlIsRequiredDurationBroken = `/api/functions/CheckVacationRequiredDuration?vacationIds=[${vacationId}]&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
                          ESS.network.sendRequest(urlIsRequiredDurationBroken).then(function (vacationDurationError){
                            if (vacationDurationError){
                              var toastId = ESS.toasts.showToast(vacationDurationError, ESS.enums.ToastType.ERROR, true);
                              functions.setValue('IsRequiredDurationBroken', true);
                            }
                            else {
                              ESS.toasts.hideToast(toastId);
                              functions.setValue('IsRequiredDurationBroken', false);
                            }
                          }); 
                        }
                        });
                      }
                    });         
                  }
                });
              }

facilityFormItem.valueChangedEventHandler:
          var recallDate = functions.getValues().RecallDate;
          var vacationId = JSON.parse(functions.getValues()['VacationId']);
          var Compensation = formItem.value;
          functions.setIsItemDisabled('NewVacationDateGrid', Compensation, 'BeginDate');
          functions.setIsItemDisabled('NewVacationDateGrid', Compensation, 'VacationDuration');
          var rows = functions.getValues().NewVacationDateGrid;
          var vacationKindIdsArray = [];
          var vacationDurationArray = [];
          rows.forEach(row => {
            if (row.rowValues.BeginDate != null && row.rowValues.VacationDuration != null) {
              vacationKindIdsArray.push(row.rowValues.VacationKindId);
              vacationDurationArray.push(row.rowValues.VacationDuration);
            };
          });

          if (vacationId){
            ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
          }

          if (vacationKindIdsArray.length > 0) {
            ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
          };
          var urlTemplate = `/api/functions/CheckExecutionShiftVacations?vacationIds=[${vacationId}]`;
          context.sendRequest(urlTemplate).then(function (errors){
            if(errors.length > 0) {
              functions.removeError(window.errorExecutionShift);
              window.errorExecutionShift = functions.showError(errors);
            } else {
              functions.removeError(window.errorExecutionShift);
            }
          });

facilityFormItem.onClickEventHandler:
        const id = 'selfRecallVacationSimplePlanningTool';
        let intervalId;
        const callDialog = () => {
          if (!Object.keys(context.canShowDialog).length) {
            const timeline = {
              type: ESS.enums.DialogItemType.TEXT,
              name: 'timeline',
              properties: {
                text: `
                  <component
                    name="VacationPlanningTool"
                    public-name="Directum_VacationPlanningTool_1_0"
                    module-name="loaders"
                    loader-name="lk-loader"
                    dialog-id="${id}"
                  />
                `,
              },
            };

            const newVacations = {
              type: ESS.enums.DialogItemType.INPUT,
                name: 'Vacations',
                properties: {
                  initialValue: JSON.stringify(functions.getValues().NewVacationDateGrid),
                  isHidden: true,
                },
            }

            const oldVacations = {
              type: ESS.enums.DialogItemType.INPUT,
                name: 'OldVacations',
                properties: {
                  initialValue: JSON.stringify([functions.getValues().VacationId]),
                  isHidden: true,
                },
            }

            const recallDate = {
              type: ESS.enums.DialogItemType.INPUT,
                name: 'RecallDate',
                properties: {
                  initialValue: functions.getValues().RecallDate,
                  isHidden: true,
                },
            }

            const performerId = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'PerformerId',
              properties: {
                initialValue: functions.getValues().InitiatorId,
                isHidden: true,
              },
            };

            const entityGuid = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'EntityGuid',
              properties: {
                initialValue: '64f4996e-265b-4b36-af64-c64630c7a900',
                isHidden: true,
              },
            };

            const compensation = {
              type: ESS.enums.DialogItemType.CHECKBOX,
              name: 'Compensation',
              properties: {
                initialValue: functions.getValues().Compensation,
                isHidden: true,
              },
            };

            const items = [
              timeline,
              performerId,
              newVacations,
              oldVacations,
              recallDate,
              entityGuid,
              compensation,
            ];

            ESS.dialogs.createDialog({
              id,
              properties: {
                width: ESS.enums.DialogWidth.WIDE,
                isFullScreen: true,
              },
              title: ESS.L('@HRPROVACATIONS.FACILITIES_SCHEDULEVACATION_DIALOG_TITLE'),
              items,
            });
            clearInterval(intervalId);
          }
        }

        intervalId = setInterval(callDialog, 300);

facility.openingEventHandler:
      context.canShowDialog = {};
      context.sendRequest = (...args) => {
        const key = Date.now();
        context.canShowDialog[key] = '';
        return ESS.network.sendRequest(...args).finally(() => delete context.canShowDialog[key]);
      };
      const initiatorId = functions.getValues().Initiator;
      context.checkEmployeeConsentSigned = ESS.scripts.HRProVacations.checkEmployeeConsentSigned;
      context.checkEmployeeConsentSigned({ functions, context, employeeId: initiatorId });
      ESS.network.sendRequest(`/api/functions/GetEmployeeCertificates`)
      .then(function (certs) {
        if (certs.length == 0) {
          ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), ESS.L('@HRPROVACATIONS.FACILITIES_SENDSTATEMENT_NO_CERTIFICATES_ERROR'));
          reject();
        } else {
          ESS.network.sendRequest(`/api/functions/GetPostListByPerson`)
          .then(function (employee){
              ESS.network.sendRequest(`/api/functions/CheckEmployeeConsentSigned`)
              .then(function (isConsentSigned) {
                if (isConsentSigned != true && employee.positions.length == 1) {
                  ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), ESS.L('@HRPROVACATIONS.FACILITIES_SHIFTVACATION_CONSENT_ERROR'));
                  reject();     
                }
                else
                {
                  const primaryId = employee.positions.find(emp => emp.isPrimary).id;
                  functions.setValue('InitiatorId', primaryId);
                  ESS.network.sendRequest(`/api/functions/GetVacationRecallStatementTemplateId?employeeId=${initiatorId}&isShiftVacation=false&isVacationRecall=true&isAuthorManager=false`)
                  .then(function (VacationStatementData) {
                    if (VacationStatementData.Error.length == 0) {
                    var templateId = JSON.parse(VacationStatementData.TemplateId);
                    var docKindId = JSON.parse(VacationStatementData.DocumentKindId);
                    functions.setValue('TemplateId', templateId);
                    functions.setValue('DocumentKindId', docKindId);
                    functions.setValue('IsFromEssAccount', true);

                    resolve();
                  } else {
                    ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), VacationStatementData.Error);
                  }
                })
                .catch(function (error) {
                  ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
                });  
              }
            });         
        })
      }
    })
    .catch(function (error) {
      ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
    });

facility.openedEventHandler:
if (!functions.getValues().RecallDate)
{
  var tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  functions.setValue('RecallDate', tomorrow);
}

facility.beforeSubmitEventHandler:
const dialogId = 'confimation-dialog';
const warningText = {
  type: ESS.enums.DialogItemType.TEXT,
  name: 'warningText',
  properties: {
    text: ESS.L('@HRPROVACATIONS.FACILITIES_SELFRECALLVACATIONEMPLOYEE_SELFRECALLWARNING'),
  },
};
const items = [warningText];
const submitButton = {
  name: 'submit-button',
  caption: ESS.L('@HRPROVACATIONS.DIALOGS_BUTTON_CONFIRM'),
  icon: 'check-mark',
  onClick: form => {
      resolve();
      ESS.dialogs.closeDialog(dialogId);
  },
  isPrimary: true,
};
const cancelButton = {
    name: 'cancel-button',
    caption: ESS.L('@HRPROVACATIONS.DIALOGS_BUTTON_CANCEL'),
    icon: 'cross',
    onClick: form => {
      ESS.dialogs.closeDialog(dialogId);
    },
  };
const buttons = [submitButton, cancelButton];
ESS.dialogs.createDialog({
    id: dialogId,
    title: ESS.L('@HRPROVACATIONS.DIALOGS_TITLE_CONFIRMACTION'),
    items,
    buttons,
    properties: {
      height: '200px',
    },
    handlers: {
      onClosed: () => reject()
    }
});
